#!/bin/bash
set -e

# Ensure data directories exist
mkdir -p "$DATA_DIR/db" "$DATA_DIR/profiles"

# Profile wrapper scripts are generated by the backend on startup (syncProfiles)
# They live in /usr/local/bin/claude-{name} and are real executables

# Start backend
echo "Starting backend on port 4201..."
node /app/server/dist/index.js &
SERVER_PID=$!

# Start frontend (Next.js standalone)
echo "Starting frontend on port 4200..."
PORT=4200 HOSTNAME=0.0.0.0 node /app/standalone/client/server.js &
CLIENT_PID=$!

# Graceful shutdown
trap "echo 'Shutting down...'; kill $SERVER_PID $CLIENT_PID 2>/dev/null; wait" SIGTERM SIGINT

echo "Agent Dashboard ready at http://localhost:4200"
wait
